package com.alkamel.onecash;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import android.graphics.Color;
import android.graphics.Typeface;
import java.util.*;
import java.io.*;

public class MainActivity extends Activity {
    Db db; LinearLayout root,body,nav; int navy=0xff102b46, blue=0xffff8a00, cyan=0xff27c6e8, bg=0xff071326, white=0xff0d2039, green=0xff1b9a68, orange=0xffff8a00, red=0xffd94b4b;
    static final int REQ_BACKUP=9001,REQ_RESTORE=9002;
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);requestPerms();showHome();}
    void requestPerms(){if(Build.VERSION.SDK_INT>=23){String[] p={android.Manifest.permission.RECEIVE_SMS,android.Manifest.permission.READ_SMS,android.Manifest.permission.SEND_SMS};List<String> missing=new ArrayList<>();for(String x:p)if(checkSelfPermission(x)!=0)missing.add(x);if(!missing.isEmpty())requestPermissions(missing.toArray(new String[0]),12);}}
    TextView txt(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(12,9,12,9);return t;}
    TextView title(String s){TextView t=txt(s,19,navy);t.setTypeface(null,Typeface.BOLD);return t;}
    Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(navy);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    View card(){LinearLayout l=col();l.setBackgroundColor(white);l.setPadding(8,8,8,8);return l;}
    void addCard(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,12);body.addView(v,p);} void addListCard(LinearLayout list,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,12);list.addView(v,p);}
    android.graphics.drawable.GradientDrawable shape(int color,int radius,int stroke){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(radius);if(stroke!=0)g.setStroke(1,stroke);return g;}
    TextView label(String s,int size,int color,boolean bold){TextView t=txt(s,size,color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    Button homeButton(String s,Runnable r,int color){Button b=btn(s,r);b.setTextSize(13);b.setMinHeight(46);b.setPadding(8,4,8,4);b.setBackground(shape(color,16,0));int brightness=(android.graphics.Color.red(color)*299+android.graphics.Color.green(color)*587+android.graphics.Color.blue(color)*114)/1000;b.setTextColor(brightness<145?white:navy);return b;}
    void base(String screen){root=col();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(bg);root.setPadding(10,6,10,6);
        LinearLayout header=col();header.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xff0b1d38,0xff10345a,0xff071326}));header.setPadding(14,10,14,10);
        TextView brand=txt("الكامل  •  "+screen,20,white);brand.setTypeface(null,Typeface.BOLD);header.addView(brand);
        header.addView(txt("أتمتة ون كاش",12,0xffc9e7ff));root.addView(header);
        ScrollView sc=new ScrollView(this);body=col();body.setPadding(4,12,4,16);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        nav=row();nav.setBackground(shape(0xff0b1d34,18,0xff17466a));nav.setGravity(Gravity.CENTER);String[][] n={{"الرئيسية","home"},{"العملاء","customers"},{"المخزون","inventory"},{"الحوالات","transfers"},{"التقارير","reports"},{"الإعدادات","settings"}};
        for(String[] x:n){Button b=new Button(this);b.setText(x[0]);b.setTextSize(10);b.setAllCaps(false);b.setPadding(0,2,0,2);b.setMinWidth(0);b.setMinHeight(42);b.setTextColor(cyan);b.setBackgroundColor(0x00000000);b.setOnClickListener(v->{switch(x[1]){case"home":showHome();break;case"customers":showCustomers();break;case"inventory":showInventory();break;case"transfers":showTransfers();break;case"reports":showReports();break;case"settings":showSettings();}});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}
        root.addView(nav);setContentView(root);
    }
    View stat(String label,String value,int color,String icon){LinearLayout c=col();c.setBackgroundColor(white);c.setPadding(14,12,14,12);TextView v=txt(icon+"  "+value,23,color);v.setTypeface(null,Typeface.BOLD);c.addView(v);c.addView(txt(label,13,0xff607489));return c;}
    void showHome(){base("الرئيسية");
        LinearLayout welcome=col();welcome.setBackground(shape(0xff0c2342,18,0xff17608a));welcome.setPadding(14,12,14,12);
        welcome.addView(label("الكامل — أتمتة ون كاش",20,white,true));welcome.addView(txt("لوحة إدارة الحوالات والمخزون",13,0xffa7c5df));addCard(welcome);
        LinearLayout stats=row();
        LinearLayout s1=col();s1.setBackground(shape(0xff102b49,16,0xff16729b));s1.setPadding(10,12,10,12);s1.addView(label("↗ "+db.countTransfers(),23,orange,true));s1.addView(txt("إجمالي الحوالات",12,0xffb4c7dc));
        LinearLayout s2=col();s2.setBackground(shape(0xff102b49,16,0xff16729b));s2.setPadding(10,12,10,12);s2.addView(label("✓ "+db.sentCount(),23,0xff48d4a0,true));s2.addView(txt("تم الإرسال",12,0xffb4c7dc));
        stats.addView(s1,new LinearLayout.LayoutParams(0,-2,1));stats.addView(s2,new LinearLayout.LayoutParams(0,-2,1));addCard(stats);
        LinearLayout pending=col();pending.setBackground(shape(0xff102743,16,0xffa75c20));pending.setPadding(12,10,12,10);pending.addView(label("⚠ حوالات تحتاج متابعة",15,white,true));pending.addView(label(db.reviewCount()+" حوالة",24,orange,true));pending.addView(homeButton("فتح سجل الحوالات  ‹",()->showTransfers(),0xff183d5c));addCard(pending);
        LinearLayout stock=col();stock.setBackground(shape(0xff0b1e36,18,0xff17608a));stock.setPadding(12,10,12,10);stock.addView(label("المخزون المتاح",18,white,true));
        int[] colors={0xff13345c,0xff302451,0xff123b35,0xff123c4c};int idx=0;
        for(int d:new int[]{100,200,250,500}){LinearLayout rr=row();rr.setBackground(shape(colors[idx++],12,0xff1b5478));rr.setPadding(8,4,8,4);TextView den=label(d+" ريال",15,0xffd9ecff,true);rr.addView(den,new LinearLayout.LayoutParams(0,-2,1));TextView q=label(db.available(d)+" كرت",16,cyan,true);rr.addView(q);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(0,5,0,5);stock.addView(rr,rp);}
        stock.addView(homeButton("إدارة المخزون واستيراد الكروت",()->showInventory(),0xff153653));addCard(stock);
        LinearLayout quick=col();quick.setBackground(shape(0xff0b1e36,18,0xff17608a));quick.setPadding(12,10,12,10);quick.addView(label("اختصارات سريعة",18,white,true));
        LinearLayout q1=row();q1.addView(homeButton("＋ تسجيل عميل",()->showCustomers(),0xff13345c),new LinearLayout.LayoutParams(0,48,1));q1.addView(homeButton("⇧ استيراد TXT",()->showInventory(),0xff3a2b1b),new LinearLayout.LayoutParams(0,48,1));quick.addView(q1);
        LinearLayout q2=row();q2.addView(homeButton("⚙ إعدادات ون كاش",()->showSettings(),0xff13345c),new LinearLayout.LayoutParams(0,48,1));q2.addView(homeButton("▤ التقارير",()->showReports(),0xff123b35),new LinearLayout.LayoutParams(0,48,1));quick.addView(q2);addCard(quick);
        boolean auto=db.setting("auto_send").equals("1");LinearLayout status=row();status.setBackground(shape(auto?0xff3b2028:0xff123b35,16,auto?red:green));status.setPadding(12,8,12,8);status.addView(label("الإرسال الآلي",14,white,true),new LinearLayout.LayoutParams(0,-2,1));status.addView(label(auto?"مفعّل":"متوقف",15,auto?red:0xff48d4a0,true));status.setOnClickListener(v->showSettings());addCard(status);
    }
    void showCustomers(){base("العملاء");EditText search=new EditText(this);search.setHint("بحث باسم العميل أو رقم الهاتف");body.addView(search);EditText name=new EditText(this);name.setHint("اسم المحوّل كما يظهر في ون كاش");EditText phone=new EditText(this);phone.setHint("رقم الجوال المستلم");phone.setInputType(3);body.addView(name);body.addView(phone);body.addView(btn("حفظ عميل جديد",()->{if(db.addCustomer(name.getText().toString(),phone.getText().toString())){toast("تم حفظ العميل");showCustomers();}else toast("تعذر الحفظ: الاسم مكرر أو البيانات ناقصة");}));
        TextView note=txt("إدارة الربط: اضغط على العميل للتعديل، واضغط مطولًا للحذف.",13,0xff64788b);body.addView(note);
        LinearLayout list=col();body.addView(list);Runnable render=()->{list.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);for(String[] c:db.customers()){if(!q.isEmpty()&&!c[0].toLowerCase(Locale.ROOT).contains(q)&&!c[1].contains(q))continue;LinearLayout item=col();item.setBackgroundColor(white);item.addView(txt(c[0],17,navy));item.addView(txt(c[1],14,blue));item.setOnClickListener(v->editCustomer(c[0],c[1]));item.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("حذف الربط؟").setMessage("لن يتم حذف سجلات الحوالات.").setPositiveButton("حذف",(a,b)->{db.deleteCustomer(c[0]);renderCustomersReload();}).setNegativeButton("إلغاء",null).show();return true;});addListCard(list,item);}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
    void renderCustomersReload(){showCustomers();}
    void editCustomer(String oldName,String oldPhone){EditText n=new EditText(this);n.setText(oldName);n.setHint("اسم العميل");EditText p=new EditText(this);p.setText(oldPhone);p.setHint("رقم الجوال");p.setInputType(3);LinearLayout l=col();l.addView(n);l.addView(p);new AlertDialog.Builder(this).setTitle("تعديل بيانات العميل").setView(l).setPositiveButton("حفظ",(d,w)->{if(db.updateCustomer(oldName,n.getText().toString(),p.getText().toString())){toast("تم التعديل");showCustomers();}else toast("تعذر التعديل — الاسم قد يكون مكررًا");}).setNegativeButton("إلغاء",null).show();}
    void showInventory(){base("المخزون");body.addView(title("رصيد الكروت حسب الفئة"));for(int n:new int[]{100,200,250,500}){LinearLayout c=col();c.setBackgroundColor(white);c.addView(txt(n+" ريال",18,navy));TextView number=txt(db.available(n)+" كرت متوفر",24,blue);number.setTypeface(null,Typeface.BOLD);c.addView(number);c.addView(btn("استيراد ملف TXT لهذه الفئة",()->pickFile(n)));addCard(c);}LinearLayout help=col();help.setBackgroundColor(0xffe6f3fc);help.addView(txt("طريقة الاستيراد",16,navy));help.addView(txt("كل سطر في الملف يحتوي رقم كرت واحد. لا تضف عنوانًا أو سعرًا. سيتم تجاهل الكروت المكررة والسطور الفارغة.",14,navy));addCard(help);}
    void pickFile(int denomination){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,denomination);}
    void showTransfers(){base("الحوالات");body.addView(btn("إعادة مطابقة الحوالات مع العملاء",()->{db.rematchPending();toast("تمت إعادة المطابقة");showTransfers();}));EditText search=new EditText(this);search.setHint("بحث باسم أو رقم أو مبلغ");body.addView(search);LinearLayout list=col();body.addView(list);Runnable render=()->{list.removeAllViews();String q=search.getText().toString().trim();List<String[]> pending=db.pendingTransfers();for(String[] p:pending){if(!q.isEmpty()&&!p[1].contains(q)&&!(p[3]!=null&&p[3].contains(q))&&!p[2].contains(q))continue;LinearLayout c=col();c.setBackgroundColor(white);TextView name=txt(p[1],17,navy);name.setTypeface(null,Typeface.BOLD);c.addView(name);c.addView(txt(p[2]+" ريال  •  "+statusArabic(p[4]),14,statusColor(p[4])));c.addView(txt("رقم المستلم: "+(p[3]==null?"غير مرتبط":p[3]),14,0xff63798b));if(p[3]!=null&&!p[3].trim().isEmpty()&&("WAITING".equals(p[4])||"FAILED".equals(p[4])))c.addView(btn("إرسال الكرت يدويًا",()->manualSend(p[0],p[1],Integer.parseInt(p[2]),p[3])));else if(p[3]==null)c.addView(txt("سجّل الاسم والرقم في العملاء ثم أعد المطابقة.",13,orange));c.addView(txt(p[4],11,0xff8a9bad));addListCard(list,c);}if(pending.isEmpty())list.addView(txt("لا توجد حوالات للمراجعة حاليًا ✓",16,green));};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();body.addView(title("آخر العمليات"));for(String s:db.recentTransfers()){LinearLayout c=col();c.setBackgroundColor(white);c.addView(txt(s,13,navy));addCard(c);}}
    void showReports(){base("التقارير");body.addView(title("ملخص العمليات"));
        LinearLayout overview=col();overview.setBackgroundColor(white);overview.addView(txt("إجمالي الحوالات المسجلة",16,navy));overview.addView(txt(String.valueOf(db.countTransfers())+" حوالة",24,blue));overview.addView(txt("حوالات اليوم: "+db.transfersToday(),16,orange));overview.addView(txt("تم الإرسال بنجاح: "+db.sentCount(),16,green));overview.addView(txt("بانتظار/مراجعة/فشل: "+db.reviewCount(),16,red));addCard(overview);
        body.addView(title("الكروت المرسلة حسب الفئة"));for(int d:new int[]{100,200,250,500}){LinearLayout item=col();item.setBackgroundColor(white);item.addView(txt(d+" ريال",17,navy));item.addView(txt(db.sentCardsByDenomination(d)+" كرت تم إرساله",20,green));item.addView(txt("المتاح حاليًا: "+db.available(d),14,blue));addCard(item);}
        body.addView(title("حالات الحوالات"));for(String[] s:new String[][]{{"SENT","تم الإرسال"},{"WAITING","بانتظار المعالجة"},{"REVIEW","تحتاج مراجعة"},{"FAILED","فشل الإرسال"},{"SENDING","جارٍ الإرسال"}}){LinearLayout item=row();item.setBackgroundColor(white);item.addView(txt(s[1],15,navy),new LinearLayout.LayoutParams(0,-2,1));item.addView(txt(String.valueOf(db.transferCountByStatus(s[0])),18,s[0].equals("SENT")?green:orange));addCard(item);}
    }
    String statusArabic(String s){switch(s){case"SENT":return"تم الإرسال";case"WAITING":return"بانتظار المعالجة";case"REVIEW":return"مراجعة";case"FAILED":return"فشل الإرسال";case"SENDING":return"جارٍ الإرسال";default:return s;}}
    int statusColor(String s){if("SENT".equals(s))return green;if("FAILED".equals(s))return red;if("REVIEW".equals(s))return orange;return blue;}
    void manualSend(String fp,String payer,int amount,String phone){new AlertDialog.Builder(this).setTitle("تأكيد إرسال الكرت").setMessage("الاسم: "+payer+"\nالمبلغ: "+amount+" ريال\nإلى: "+phone+"\nهل تريد حجز كرت وإرساله؟").setPositiveButton("إرسال",(d,w)->{long card=db.reserveCard(amount);if(card<0){toast("لا يوجد مخزون لهذه الفئة");return;}String code=db.cardCode(card);if(code==null){db.cardState(card,"AVAILABLE");toast("تعذر قراءة الكرت");return;}db.attachCardToTransfer(fp,card);Intent sentIntent=new Intent(this,SmsSentReceiver.class).setAction("com.alkamel.onecash.SMS_SENT").putExtra("fp",fp).putExtra("card",card);PendingIntent sent=PendingIntent.getBroadcast(this,fp.hashCode(),sentIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{android.telephony.SmsManager.getDefault().sendTextMessage(phone,null,"حوالتك وصلت. كرت "+amount+" ريال: "+code+" - الكامل",sent,null);toast("بدأ إرسال SMS. تابع حالة الحوالة.");}catch(Exception e){db.cardState(card,"AVAILABLE");db.updateTransfer(fp,"FAILED","فشل الإرسال: "+e.getMessage());toast("فشل الإرسال");}showTransfers();}).setNegativeButton("إلغاء",null).show();}
    void showSettings(){base("الإعدادات");LinearLayout senderCard=col();senderCard.setBackgroundColor(white);senderCard.addView(title("مرسل ون كاش"));EditText sender=new EditText(this);sender.setHint("Sender ID / رقم المرسل");sender.setText(db.setting("wallet_sender"));senderCard.addView(sender);senderCard.addView(btn("حفظ المرسل",()->{db.setSetting("wallet_sender",sender.getText().toString().trim());toast("تم حفظ المرسل");}));addCard(senderCard);
        LinearLayout auto=col();auto.setBackgroundColor(white);auto.addView(title("الإرسال التلقائي"));Switch sw=new Switch(this);sw.setText("تفعيل إرسال الكرت تلقائيًا");sw.setChecked(db.setting("auto_send").equals("1"));auto.addView(sw);auto.addView(txt("عند التفعيل: لا يتم إرسال الكرت إلا عند تطابق المرسل والاسم والمبلغ وتوفر المخزون. يُنصح بالاختبار قبل الاستخدام الحقيقي.",14,0xff607489));auto.addView(btn("حفظ إعداد الإرسال",()->{if(sw.isChecked())new AlertDialog.Builder(this).setTitle("تنبيه").setMessage("تأكد من صحة المرسل وربط العملاء والمخزون، واختبر على رقم تجريبي.").setPositiveButton("تفعيل",(a,b)->{db.setSetting("auto_send","1");showSettings();}).setNegativeButton("إلغاء",null).show();else{db.setSetting("auto_send","0");showSettings();}}));addCard(auto);
        LinearLayout data=col();data.setBackgroundColor(white);data.addView(title("البيانات والنسخ الاحتياطي"));data.addView(btn("إنشاء نسخة احتياطية",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"alkamel-onecash-backup.db"),REQ_BACKUP)));data.addView(btn("استعادة نسخة",()->new AlertDialog.Builder(this).setTitle("استعادة النسخة").setMessage("الاستعادة تستبدل البيانات الحالية. خذ نسخة احتياطية قبل المتابعة.").setPositiveButton("متابعة اختيار الملف",(a,b)->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),REQ_RESTORE)).setNegativeButton("إلغاء",null).show()));data.addView(txt("البيانات محفوظة محليًا على الجهاز. لا يوجد اتصال بسيرفر خارجي.",14,0xff607489));addCard(data);
        LinearLayout about=col();about.setBackgroundColor(white);about.addView(title("حول التطبيق"));about.addView(txt("الكامل — أتمتة ون كاش\nالإصدار 0.7.0\nواجهة عربية • حفظ محلي • إدارة مخزون • متابعة حوالات",14,navy));addCard(about);}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null)return;try{Uri u=data.getData();if(requestCode==REQ_BACKUP){db.close();try(InputStream in=new FileInputStream(getDatabasePath("onecash.db"));OutputStream out=getContentResolver().openOutputStream(u)){copy(in,out);}db=new Db(this);toast("تم حفظ النسخة الاحتياطية");showSettings();return;}if(requestCode==REQ_RESTORE){db.close();try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(getDatabasePath("onecash.db"))){copy(in,out);}db=new Db(this);toast("تمت الاستعادة");showHome();return;}if(requestCode>=100){try(InputStream in=getContentResolver().openInputStream(u);BufferedReader r=new BufferedReader(new InputStreamReader(in,"UTF-8"))){List<String> codes=new ArrayList<>();String line;while((line=r.readLine())!=null)codes.add(line.trim());int n=db.importCards(requestCode,codes);toast("تم استيراد "+n+" كرت جديد");showInventory();}}}catch(Exception e){toast("تعذر إكمال العملية: "+e.getMessage());if(db==null)db=new Db(this);}}
    void copy(InputStream in,OutputStream out)throws IOException{byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n); }
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override protected void onDestroy(){if(db!=null)db.close();super.onDestroy();}
}
